package app.xiaohe.tests;
import android.content.Context;import org.json.*;import app.xiaohe.assistant.*;import java.util.*;import java.time.*;import android.database.sqlite.SQLiteDatabase;

public final class VolumeSmoke {
  public static void run(Store db)throws Exception {
    JSONArray entities=new MemoryLedger(db).findEntity("小林");JSONObject person=null;for(int i=0;i<entities.length();i++)if(entities.getJSONObject(i).optString("qualifier").equals("同事"))person=entities.getJSONObject(i);if(person==null)throw new AssertionError("Volume fixture missing");String eid=person.getString("id");JSONObject source=db.message("user","多条本机记忆检索测试",new JSONArray(),UUID.randomUUID().toString());SQLiteDatabase sql=db.getWritableDatabase();long started=System.currentTimeMillis();sql.beginTransaction();try{for(int i=0;i<1200;i++){long event=OffsetDateTime.parse("2027-01-01T10:00:00+08:00").toInstant().toEpochMilli()+i*3600000L;JSONObject r=new JSONObject().put("id",UUID.randomUUID().toString()).put("created",System.currentTimeMillis()+i).put("sourceId",source.getString("id")).put("status","active").put("type",i%2==0?"event":"note").put("kind",i%2==0?"event":"note").put("title","散步记录 "+i).put("content","和同事小林散步，路上看到了树。标记"+i).put("tags",new JSONArray().put("检索测试")).put("subjectId",eid).put("subjectLabel","小林 · 同事").put("entityIds",new JSONArray().put(eid)).put("eventState","occurred").put("time",new JSONObject().put("state","resolved").put("raw","2027年1月1日").put("start",event).put("end",event+60000));if(i==1111)r.put("title","大批记忆中的唯一线索").put("content","青柠梅子书签是一条检索线索");db.put("memories",r);}sql.setTransactionSuccessful();}finally{sql.endTransaction();}
    MemoryLedger ledger=new MemoryLedger(db);JSONObject page=ledger.page(new JSONObject().put("status","all").put("query","青柠梅子书签"));if(page.getJSONArray("rows").length()!=1)throw new AssertionError("FTS must find one old record beyond bootstrap window");JSONObject boot=db.bootstrap();if(boot.getJSONArray("memories").length()>250||boot.getInt("memoryCount")<1200)throw new AssertionError("Bootstrap must remain bounded");JSONArray last=ledger.search("上次和同事小林吃饭是什么时候",10,source);if(last.length()==0||!last.getJSONObject(0).optString("title").contains("吃饭"))throw new AssertionError("Old relevant occurrence must beat hundreds of unrelated new records");if(ledger.search("同事小林现在的咖啡偏好",10,source).length()==0)throw new AssertionError("Old current fact must remain retrievable");JSONObject more=ledger.page(new JSONObject().put("status","all").put("offset",1100).put("limit",40));if(more.getJSONArray("rows").length()!=40)throw new AssertionError("Deep pagination must advance");System.out.println("Volume test: "+boot.getInt("memoryCount")+" memories, "+(System.currentTimeMillis()-started)+" ms including inserts; indexed retrieval and bounded bootstrap passed");
  }
}
